const $=(id)=>document.getElementById(id); let callId=null; const hot=["This is Dana Morgan from Northwind Manufacturing in CA. I'm the procurement director.","We need 12000 hex bolts this week. Call me at 425-555-0193 and email dana@northwind.example."];async function post(url,body){return fetch(url,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body??{})}).then(r=>r.json())}function line(role,text){const li=document.createElement("li");li.className=role;li.textContent=`${role}: ${text}`;$('transcript').append(li)}function render(s){ if(!s)return; $('draft').textContent=JSON.stringify(s.draft,null,2); $('score').textContent=JSON.stringify({state:s.state,score:s.score,owner:s.owner,savedLeadId:s.savedLeadId,outcome:s.outcome},null,2); refreshOutbox(); refreshStats(); }async function refreshOutbox(){ $('outbox').textContent=JSON.stringify(await fetch('/api/outbox').then(r=>r.json()),null,2)}async function refreshStats(){ $('stats').textContent=JSON.stringify(await fetch('/api/stats').then(r=>r.json())) }function ws(){const proto=location.protocol==='https:'?'wss:':'ws:';const s=new WebSocket(`${proto}//${location.host}/ws/hub?user=*`);s.onmessage=(ev)=>{const m=JSON.parse(ev.data);const p=m.arguments?.[0];if(callId&&p.callId!==callId)return;if(m.target==='transcript')line(p.role,p.text); if(m.target==='event')$('events').append(Object.assign(document.createElement('li'),{textContent:`${p.kind} ${p.detail??''}`})); if(m.target==='state')render(p)};s.onclose=()=>setTimeout(ws,1000)}$('newCall').onclick=async()=>{$('transcript').innerHTML='';$('events').innerHTML='';const r=await post('/api/simulate',{});callId=r.callId;render(r.snapshot);$('say').disabled=false;$('sayBtn').disabled=false;$('silence').disabled=false};$('hotFixture').onclick=async()=>{const r=await post('/api/simulate',{transcript:hot});callId=r.callId;for(const t of r.snapshot.transcript) line(t.role,t.text);render(r.snapshot)};$('sayForm').onsubmit=async(e)=>{e.preventDefault();const text=$('say').value.trim();if(!text||!callId)return;$('say').value='';line('caller',text);const r=await post(`/api/simulate/${callId}/say`,{text});render(r.snapshot)};$('silence').onclick=async()=>render((await post(`/api/simulate/${callId}/silence`)).snapshot);fetch('/health').then(r=>r.json()).then(h=>{$('mode').textContent=h.callReady?`live · ${h.voiceLive.model}`:'simulation — no Azure configured'});ws();refreshStats();refreshOutbox();